'use client';
import { useEffect, useId, useState, type CSSProperties } from 'react';
import { useStudioMotion } from '../../motion';
import type { EffectProps } from '../../types';
import styles from './styles.module.css';

type Params = { sequence: string; duration: number; orbit: number; thickness: number; satellite: boolean };
type Phase = 'preparing' | 'exporting' | 'done';

const PREP = 1400; // ms of "unknown size" before the job reports progress
const TICK = 180;

function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const STATUS: Record<Phase, string> = {
  preparing: 'Preparing export…',
  exporting: 'Exporting. Progress is shown as a percentage.',
  done: 'Export complete: harbour-lights.mov (sample job).',
};

export default function ProgressOrbitLoader({ params }: EffectProps<Params>) {
  const { reduced } = useStudioMotion();
  const uid = useId();
  const sequence = params.sequence === 'determinate' || params.sequence === 'indeterminate' ? params.sequence : 'auto';
  const first: Phase = sequence === 'determinate' ? 'exporting' : 'preparing';
  const [run, setRun] = useState(0);
  const [phase, setPhase] = useState<Phase>(first);
  const [value, setValue] = useState(0);

  // Restart whenever the sequence changes (and on the Restart button via `run`).
  useEffect(() => { setPhase(first); setValue(0); }, [first, run]);

  // Unknown size first, then hand over to determinate progress (auto sequence only).
  useEffect(() => {
    if (phase !== 'preparing' || sequence !== 'auto') return;
    const t = window.setTimeout(() => setPhase('exporting'), PREP);
    return () => window.clearTimeout(t);
  }, [phase, sequence, run]);

  // Simulated job: irregular chunks that average out to `duration`.
  useEffect(() => {
    if (phase !== 'exporting') return;
    const rnd = mulberry32(run * 7919 + 17);
    const mean = 100 / Math.max(1, params.duration / TICK);
    let v = 0;
    let timer = 0;
    const tick = () => {
      v = Math.min(100, v + mean * (0.3 + rnd() * 1.4));
      setValue(v);
      timer = v >= 100 ? window.setTimeout(() => setPhase('done'), 420) : window.setTimeout(tick, TICK);
    };
    timer = window.setTimeout(tick, TICK);
    return () => window.clearTimeout(timer);
  }, [phase, run, params.duration]);

  const known = phase !== 'preparing';
  const pct = phase === 'done' ? 100 : Math.floor(value);
  const progress = phase === 'done' ? 1 : value / 100;
  const step = phase === 'preparing' ? 'Step 1 of 2 · reading clips' : phase === 'exporting' ? 'Step 2 of 2 · encoding' : 'Finished · 2 of 2 steps';

  const style = {
    '--thick': params.thickness,
    '--orbit': `${params.orbit}ms`,
  } as CSSProperties;

  return (
    <div className={styles.root} data-reduced={reduced || undefined} data-mode={known ? 'determinate' : 'indeterminate'} data-phase={phase} style={style}>
      <section className={styles.card} aria-labelledby={`${uid}title`}>
        <header className={styles.head}>
          <div>
            <p className={styles.kicker}>Export queue · sample job</p>
            <h3 id={`${uid}title`} className={styles.title}>harbour-lights.mov</h3>
          </div>
          <button type="button" className={styles.restart} onClick={() => setRun((r) => r + 1)}>Restart</button>
        </header>

        <div
          className={styles.loader}
          role="progressbar"
          aria-labelledby={`${uid}title`}
          aria-valuemin={0}
          aria-valuemax={100}
          aria-valuenow={known ? pct : undefined}
          aria-valuetext={known ? `${pct}% exported` : 'Preparing, size not known yet'}
        >
          <svg className={styles.svg} viewBox="0 0 120 120" aria-hidden="true" focusable="false">
            <circle className={styles.orbitPath} cx="60" cy="60" r="56" />
            <circle className={styles.track} cx="60" cy="60" r="44" />
            {known ? (
              <circle className={styles.arc} cx="60" cy="60" r="44" pathLength={1} transform="rotate(-90 60 60)" style={{ strokeDashoffset: 1 - progress }} />
            ) : (
              <g className={styles.spin}>
                <circle className={styles.indet} cx="60" cy="60" r="44" pathLength={1} transform="rotate(-90 60 60)" />
              </g>
            )}
            {params.satellite ? (
              <g className={styles.satellite} data-free={!known || undefined} style={known ? { transform: `rotate(${progress * 360}deg)` } : undefined}>
                <circle cx="60" cy="4" r="3.25" />
              </g>
            ) : null}
          </svg>
          <div className={styles.readout} aria-hidden="true">
            {known ? (
              <span className={styles.num}>{pct}<span className={styles.pct}>%</span></span>
            ) : (
              <span className={styles.dots}>···</span>
            )}
            <span className={styles.label}>{phase === 'preparing' ? 'Preparing' : phase === 'exporting' ? 'Exporting' : 'Done'}</span>
          </div>
        </div>

        <footer className={styles.foot}>
          <span>{step}</span>
          <span>{sequence === 'auto' ? 'Indeterminate → determinate' : sequence === 'determinate' ? 'Determinate only' : 'Indeterminate only'}</span>
        </footer>
        <p className={styles.srOnly} role="status">{STATUS[phase]}</p>
      </section>
    </div>
  );
}

.root {
  box-sizing: border-box;
  container-type: inline-size;
  width: min(100% - 2rem, 30rem);
  margin: clamp(1.25rem, 4cqi, 2.5rem) auto;
  color: var(--s3-ink, #11110f);
  font-family: var(--s3-font-text, ui-sans-serif, system-ui, sans-serif);
}
.card {
  display: grid;
  gap: clamp(1rem, 5cqi, 1.75rem);
  padding: clamp(1rem, 5cqi, 1.75rem);
  border: 1px solid var(--s3-line, #11110f24);
  border-radius: var(--s3-radius-l, 18px);
  background: var(--s3-surface, #fbf9f4);
}
.head { display: flex; align-items: flex-start; justify-content: space-between; gap: 1rem; }
.kicker, .foot {
  margin: 0;
  font-family: var(--s3-font-mono, ui-monospace, monospace);
  font-size: 0.6875rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--s3-ink-muted, #5c5a52);
}
.title {
  margin: 0.375rem 0 0;
  font-family: var(--s3-font-display, ui-sans-serif, system-ui, sans-serif);
  font-size: clamp(1.25rem, 5cqi, 1.625rem);
  font-weight: 700;
  line-height: 1.05;
  letter-spacing: -0.03em;
  overflow-wrap: anywhere;
}
.restart {
  flex: none;
  min-height: 2.5rem;
  padding: 0 1rem;
  border: 1px solid var(--s3-line-strong, #11110f);
  border-radius: 999px;
  background: transparent;
  color: var(--s3-ink, #11110f);
  font: inherit;
  font-size: 0.875rem;
  font-weight: 600;
  cursor: pointer;
}
.restart:focus-visible { outline: 2px solid var(--s3-focus, #1d4ed8); outline-offset: 2px; }
@media (hover: hover) { .restart:hover { background: var(--s3-surface-2, #e9e5da); } }

/* ── Loader ───────────────────────────────────────────────────────────── */
.loader { position: relative; justify-self: center; width: clamp(10rem, 46cqi, 13rem); aspect-ratio: 1; }
.svg { display: block; width: 100%; height: 100%; overflow: visible; }
.orbitPath { fill: none; stroke: var(--s3-ink-muted, #5c5a52); stroke-width: 1.25; stroke-linecap: round; stroke-dasharray: 0.1 5.2; }
.track { fill: none; stroke: color-mix(in oklab, var(--s3-ink, #11110f) 12%, transparent); stroke-width: var(--thick, 6); }
.arc, .indet { fill: none; stroke: var(--s3-signal, #bf2f09); stroke-width: var(--thick, 6); stroke-linecap: round; }
.arc { stroke-dasharray: 1; transition: stroke-dashoffset 300ms var(--s3-ease-standard, ease); }
.root[data-phase='done'] .arc { stroke: var(--s3-ink, #11110f); }

/* Indeterminate: eased turns on the group, breathing dash on the circle — two periods, never in lockstep. */
.spin, .satellite { transform-box: view-box; transform-origin: 60px 60px; }
.indet { stroke-dasharray: 0.26 1; }
.root:not([data-reduced]) .spin { animation: orbit var(--orbit, 1500ms) var(--s3-ease-inOut, ease-in-out) infinite; }
.root:not([data-reduced]) .indet { animation: breathe calc(var(--orbit, 1500ms) * 1.6) var(--s3-ease-inOut, ease-in-out) infinite; }
@keyframes orbit { to { transform: rotate(360deg); } }
@keyframes breathe {
  0%, 100% { stroke-dasharray: 0.06 1; stroke-dashoffset: 0; }
  50% { stroke-dasharray: 0.46 1; stroke-dashoffset: -0.14; }
}

.satellite circle { fill: var(--s3-ink, #11110f); }
.satellite { transition: transform 300ms var(--s3-ease-standard, ease); }
.root:not([data-reduced]) .satellite[data-free] { animation: orbit calc(var(--orbit, 1500ms) * 2.3) var(--s3-ease-emphasized, ease-out) infinite; }

.readout {
  position: absolute;
  inset: 0;
  display: grid;
  place-content: center;
  justify-items: center;
  gap: 0.25rem;
  pointer-events: none;
}
.num {
  font-family: var(--s3-font-display, ui-sans-serif, system-ui, sans-serif);
  font-size: clamp(2.25rem, 12cqi, 3rem);
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.04em;
  font-variant-numeric: tabular-nums;
}
.pct { margin-left: 0.05em; font-size: 0.45em; font-weight: 600; letter-spacing: 0; vertical-align: 0.9em; }
.dots { font-family: var(--s3-font-display, ui-sans-serif, system-ui, sans-serif); font-size: 2.25rem; line-height: 1; letter-spacing: 0.05em; color: var(--s3-ink-muted, #5c5a52); }
.label {
  font-family: var(--s3-font-mono, ui-monospace, monospace);
  font-size: 0.6875rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--s3-ink-muted, #5c5a52);
}

.foot { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 0.25rem 1rem; padding-top: 0.875rem; border-top: 1px solid var(--s3-line, #11110f24); }
.srOnly { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }

/* Reduced motion: static quarter ring while indeterminate; determinate updates land without easing. */
.root[data-reduced] .arc,
.root[data-reduced] .satellite { transition: none; }
